2: import { zoneContains } from './zones';
3: import { scaleVec3 } from './vec';
4: 
5: export class TeleporterObstacle implements BallObstacle<TeleporterConfig> {
6:   public readonly id: string;
7:   public readonly kind = 'teleporter' as const;
8:   public readonly config: TeleporterConfig;
9:   public enabled: boolean;
10:   private hasTeleported = false;
11: 
12:   constructor(config: TeleporterConfig) {
13:     this.id = config.id;
14:     this.config = config;
15:     this.enabled = config.enabled ?? true;
16:   }
17: 
18:   update(ball: BallSample, _context: ObstacleStepContext): ObstacleEffect | null {
19:     if (!this.enabled || this.hasTeleported) return null;
20:     if (zoneContains(this.config.entryZone, ball.position, ball.radius ?? 0.1)) {
21:       this.hasTeleported = true;
22:       const exitVel = this.config.exitVelocityScale !== undefined
23:         ? scaleVec3(ball.velocity, this.config.exitVelocityScale)
24:         : ball.velocity;
25: 
26:       return {
27:         obstacleId: this.id,
28:         kind: this.kind,
29:         teleport: {
30:           position: this.config.exitPosition,
31:           velocity: exitVel,
32:           clearAngularVelocity: this.config.clearAngularVelocity ?? true,
33:         },
34:       };
35:     }
36:     return null;
37:   }
38: 
39:   reset(): void {
40:     this.hasTeleported = false;
