1: import type { BallObstacle, BallSample, FanConfig, ObstacleEffect, ObstacleStepContext } from './types';
2: import { zoneContains, zoneFalloff } from './zones';
3: import { scaleVec3 } from './vec';
4: 
5: export class FanObstacle implements BallObstacle<FanConfig> {
6:   public readonly id: string;
7:   public readonly kind = 'fan' as const;
8:   public readonly config: FanConfig;
9:   public enabled: boolean;
10: 
11:   constructor(config: FanConfig) {
12:     this.id = config.id;
13:     this.config = config;
14:     this.enabled = config.enabled ?? true;
15:   }
16: 
17:   update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null {
18:     if (!this.enabled) return null;
19:     if (!zoneContains(this.config.zone, ball.position, ball.radius ?? 0.1)) return null;
20: 
21:     const falloff = this.config.falloff !== false ? zoneFalloff(this.config.zone, ball.position) : 1;
22:     if (falloff <= 0) return null;
23: 
24:     let multiplier = 1;
25:     if (this.config.pulse) {
26:       const { period, minMultiplier } = this.config.pulse;
27:       if (period > 0) {
28:         const t = (context.elapsed % period) / period;
29:         multiplier = minMultiplier + (1 - minMultiplier) * (0.5 + 0.5 * Math.sin(t * Math.PI * 2));
30:       }
31:     }
32: 
33:     const force = this.config.maxForce * falloff * multiplier * context.dt;
34:     const deltaV = scaleVec3(this.config.direction, force);
35: 
36:     return {
37:       obstacleId: this.id,
38:       kind: this.kind,
39:       deltaVelocity: deltaV,
40:     };
41:   }
42: 
43:   reset(): void {}
44: }
